INSERT INTO templates (
  title, description, template_type, target_feature, usage_type, display_config, source, cover_url, preview_url,
  prompt, params_json, ratio, duration, scene, category_id, tags_json, sort_order, is_recommended, is_hot,
  is_enabled, visibility, status, review_status, access_level, visibility_scope, usage_scope, created_at, updated_at
)
SELECT
  seed.title,
  seed.description,
  seed.template_type,
  seed.target_feature,
  seed.usage_type,
  seed.display_config,
  seed.source,
  seed.cover_url,
  seed.preview_url,
  seed.prompt,
  seed.params_json,
  seed.ratio,
  seed.duration,
  seed.scene,
  category.id,
  seed.tags_json,
  seed.sort_order,
  seed.is_recommended,
  seed.is_hot,
  1,
  'public',
  'approved',
  'approved',
  'free',
  'all',
  'all',
  NOW(3),
  NOW(3)
FROM tmp_template_seeds_20260531_008 seed
JOIN template_categories category ON category.category_key = seed.category_key
WHERE NOT EXISTS (
  SELECT 1
    FROM templates existing
   WHERE existing.deleted_at IS NULL
     AND existing.template_type = seed.template_type
     AND JSON_UNQUOTE(JSON_EXTRACT(existing.params_json, '$.source')) = seed.source_key
     AND JSON_UNQUOTE(JSON_EXTRACT(existing.params_json, '$.sourceId')) = seed.source_id
);

DROP TEMPORARY TABLE IF EXISTS tmp_template_seeds_20260531_008;
